package bench

import (
	"fmt"
	"html"
	"io"
	"math"
	"strings"
)

// A deliberately small SVG bar-chart writer, so the documentation's graphs
// are regenerated by `bench plot` from the result files without any
// plotting dependency.

var seriesColors = []string{"#6b7280", "#2563eb", "#d97706", "#059669"}

// colorFor picks series colours: two-series charts are a grey "before" and
// a blue "after".
func (c *BarChart) colorFor(i int) string {
	if len(c.Series) == 2 && i == 1 {
		return seriesColors[1]
	}
	return seriesColors[i%len(seriesColors)]
}

func (c *BarChart) subtitleLines() []string {
	if c.Subtitle == "" {
		return nil
	}
	return strings.Split(c.Subtitle, "\n")
}

// BarChart is a grouped bar chart: one group per category, one bar per
// series, with min–max whiskers over the runs.
type BarChart struct {
	Title, YLabel string
	// Subtitle states the benchmark conditions; lines are separated by \n.
	Subtitle   string
	Categories []string
	// Labels, if set, are shown instead of Categories (same order).
	Labels      []string
	Series      []string
	Med, Lo, Hi [][]float64 // [series][category]
	// ValueLabels prints each bar's median above it.
	ValueLabels bool
}

func niceMax(v float64) float64 {
	if v <= 0 {
		return 1
	}
	exp := math.Pow(10, math.Floor(math.Log10(v)))
	for _, m := range []float64{1, 2, 2.5, 5, 10} {
		if v <= m*exp {
			return m * exp
		}
	}
	return 10 * exp
}

// WriteSVG renders the chart.
func (c *BarChart) WriteSVG(w io.Writer) {
	const (
		width, height   = 960.0, 460.0
		left, right     = 70.0, 20.0
		bottom          = 130.0
		legendRowHeight = 16.0
	)
	sub := c.subtitleLines()
	top := 56.0 + 15*float64(len(sub))
	plotW, plotH := width-left-right, height-top-bottom
	var maxV float64
	for _, s := range c.Hi {
		for _, v := range s {
			maxV = math.Max(maxV, v)
		}
	}
	yMax := niceMax(maxV * 1.05)
	y := func(v float64) float64 { return top + plotH*(1-v/yMax) }

	fmt.Fprintf(w, `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 %.0f %.0f" font-family="system-ui, sans-serif" font-size="12" role="img" aria-label="%s">`+"\n", width, height, html.EscapeString(c.Title))
	fmt.Fprintf(w, `<title>%s</title>`+"\n", html.EscapeString(c.Title))
	fmt.Fprintf(w, `<rect width="%.0f" height="%.0f" fill="#ffffff"/>`+"\n", width, height)
	fmt.Fprintf(w, `<text x="%.0f" y="22" font-size="15" font-weight="600" fill="#111827">%s</text>`+"\n", left, html.EscapeString(c.Title))
	for i, line := range sub {
		fmt.Fprintf(w, `<text x="%.0f" y="%.0f" font-size="11" fill="#4b5563">%s</text>`+"\n", left, 38+15*float64(i), html.EscapeString(line))
	}
	legendY := 42 + 15*float64(len(sub))
	lx := left
	for i, s := range c.Series {
		fmt.Fprintf(w, `<rect x="%.0f" y="%.0f" width="10" height="10" fill="%s"/><text x="%.0f" y="%.0f" fill="#374151">%s</text>`+"\n", lx, legendY-9, c.colorFor(i), lx+14, legendY, html.EscapeString(s))
		lx += 24 + 7*float64(len(s))
	}
	for i := 0; i <= 5; i++ {
		v := yMax * float64(i) / 5
		fmt.Fprintf(w, `<line x1="%.0f" x2="%.0f" y1="%.1f" y2="%.1f" stroke="#e5e7eb"/><text x="%.0f" y="%.1f" text-anchor="end" fill="#6b7280">%s</text>`+"\n",
			left, width-right, y(v), y(v), left-6, y(v)+4, trimFloat(v))
	}
	fmt.Fprintf(w, `<text transform="translate(16,%.0f) rotate(-90)" text-anchor="middle" fill="#374151">%s</text>`+"\n", top+plotH/2, html.EscapeString(c.YLabel))

	groupW := plotW / float64(len(c.Categories))
	maxBar := 28.0
	if c.ValueLabels {
		maxBar = 56 // room for the value labels of neighbouring bars
	}
	barW := math.Min(maxBar, groupW*0.8/float64(len(c.Series)))
	for ci, cat := range c.Categories {
		gx := left + groupW*float64(ci) + groupW/2
		for si := range c.Series {
			x := gx + (float64(si)-float64(len(c.Series))/2)*barW
			med, lo, hi := c.Med[si][ci], c.Lo[si][ci], c.Hi[si][ci]
			fmt.Fprintf(w, `<rect x="%.1f" y="%.1f" width="%.1f" height="%.1f" fill="%s"><title>%s, %s: median %s (min %s, max %s)</title></rect>`+"\n",
				x, y(med), barW-2, y(0)-y(med), c.colorFor(si), html.EscapeString(c.Series[si]), html.EscapeString(cat), trimFloat(med), trimFloat(lo), trimFloat(hi))
			cx := x + (barW-2)/2
			fmt.Fprintf(w, `<line x1="%.1f" x2="%.1f" y1="%.1f" y2="%.1f" stroke="#111827" stroke-width="1"/>`, cx, cx, y(lo), y(hi))
			if c.ValueLabels {
				fmt.Fprintf(w, `<text x="%.1f" y="%.1f" text-anchor="middle" font-size="11" font-weight="600" fill="#111827">%s</text>`, cx, y(hi)-5, thousands(med))
			}
			fmt.Fprintf(w, `<line x1="%.1f" x2="%.1f" y1="%.1f" y2="%.1f" stroke="#111827"/><line x1="%.1f" x2="%.1f" y1="%.1f" y2="%.1f" stroke="#111827"/>`+"\n",
				cx-3, cx+3, y(lo), y(lo), cx-3, cx+3, y(hi), y(hi))
		}
		label := cat
		if ci < len(c.Labels) {
			label = c.Labels[ci]
		}
		fmt.Fprintf(w, `<text transform="translate(%.1f,%.1f) rotate(-40)" text-anchor="end" fill="#374151">%s</text>`+"\n", gx+4, top+plotH+14, html.EscapeString(label))
	}
	fmt.Fprintf(w, `<line x1="%.0f" x2="%.0f" y1="%.1f" y2="%.1f" stroke="#9ca3af"/>`+"\n", left, width-right, y(0), y(0))
	fmt.Fprintf(w, `<text x="%.0f" y="%.0f" fill="#6b7280" font-size="11">Bars: median of the runs. Whiskers: min–max.</text>`+"\n", left, height-6)
	_ = legendRowHeight
	fmt.Fprintln(w, `</svg>`)
}

// thousands formats v rounded to an integer with thousands separators.
func thousands(v float64) string {
	n := int64(math.Round(v))
	s := fmt.Sprintf("%d", n)
	for i := len(s) - 3; i > 0 && s[i-1] != '-'; i -= 3 {
		s = s[:i] + "," + s[i:]
	}
	return s
}

func trimFloat(v float64) string {
	s := fmt.Sprintf("%.1f", v)
	if strings.HasSuffix(s, ".0") {
		return strings.TrimSuffix(s, ".0")
	}
	return s
}

// ChartFromArms builds a chart of one metric over the scenarios common to
// the arms. value extracts the metric from a result.
func ChartFromArms(title, ylabel string, arms []Arm, scenarios []string, value func(*Result) float64) *BarChart {
	c := &BarChart{Title: title, YLabel: ylabel, Categories: scenarios}
	for _, a := range arms {
		c.Series = append(c.Series, a.Label)
		var med, lo, hi []float64
		for _, n := range scenarios {
			var v []float64
			for _, r := range a.Results {
				if r.Scenario.Name == n {
					v = append(v, value(r))
				}
			}
			l, h := rangeOf(v)
			med, lo, hi = append(med, medianOf(v)), append(lo, l), append(hi, h)
		}
		c.Med, c.Lo, c.Hi = append(c.Med, med), append(c.Lo, lo), append(c.Hi, hi)
	}
	return c
}

// OutcomeGroup summarises the oracle's verdict over a set of runs.
type OutcomeGroup struct {
	Label            string
	Runs, Passed     int
	LedgerViolations int64 // db.* checks (balanced entries, balances, one capture per payment, ...)
	DuplicateCharges int64 // processor.no_duplicate_charges
	Deadlocks        int64 // pg_stat_database
	// ByDesign marks a group in which failures are the expected result (the
	// protections are switched off); it is drawn with an explanatory note.
	ByDesign bool
	Note     string
}

// GroupFromResults counts the oracle's verdicts over results.
func GroupFromResults(label string, results []*Result, byDesign bool, note string) OutcomeGroup {
	g := OutcomeGroup{Label: label, ByDesign: byDesign, Note: note}
	for _, r := range results {
		g.Runs++
		if r.Oracle != nil && r.Oracle.Passed {
			g.Passed++
		}
		g.DuplicateCharges += checkViolations(r.Oracle, "processor.no_duplicate_charges")
		if r.Oracle != nil {
			for _, c := range r.Oracle.Checks {
				if strings.HasPrefix(c.Name, "db.") {
					g.LedgerViolations += c.Violations
				}
			}
		}
		if r.Database != nil {
			g.Deadlocks += r.Database.Deadlocks
		}
	}
	return g
}

// WriteOutcomesSVG draws, for each group, the share of runs that passed
// every oracle check (green) and failed (red) with the counts behind it.
func WriteOutcomesSVG(w io.Writer, title, subtitle string, groups []OutcomeGroup) {
	const (
		width           = 960.0
		left, barW      = 20.0, 330.0
		rowH            = 64.0
		colLedger       = 600.0
		colDup, colDead = 720.0, 840.0
	)
	sub := []string(nil)
	if subtitle != "" {
		sub = strings.Split(subtitle, "\n")
	}
	top := 48.0 + 15*float64(len(sub))
	head := top + 26
	height := head + rowH*float64(len(groups)) + 40
	fmt.Fprintf(w, `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 %.0f %.0f" font-family="system-ui, sans-serif" font-size="12" role="img" aria-label="%s">`+"\n", width, height, html.EscapeString(title))
	fmt.Fprintf(w, `<title>%s</title><rect width="%.0f" height="%.0f" fill="#ffffff"/>`+"\n", html.EscapeString(title), width, height)
	fmt.Fprintf(w, `<text x="%.0f" y="22" font-size="15" font-weight="600" fill="#111827">%s</text>`+"\n", left, html.EscapeString(title))
	for i, line := range sub {
		fmt.Fprintf(w, `<text x="%.0f" y="%.0f" font-size="11" fill="#4b5563">%s</text>`+"\n", left, 38+15*float64(i), html.EscapeString(line))
	}
	fmt.Fprintf(w, `<text x="%.0f" y="%.0f" font-size="11" fill="#6b7280">runs that passed every oracle check</text>`+"\n", left, head-6)
	for _, x := range []struct {
		at   float64
		text string
	}{{colLedger, "ledger invariant"}, {colDup, "duplicate"}, {colDead, "deadlocks"}} {
		fmt.Fprintf(w, `<text x="%.0f" y="%.0f" font-size="11" fill="#6b7280" text-anchor="middle">%s</text>`+"\n", x.at, head-16, x.text)
		sec := "violations"
		if x.text == "duplicate" {
			sec = "charges"
		} else if x.text == "deadlocks" {
			sec = "(PostgreSQL)"
		}
		fmt.Fprintf(w, `<text x="%.0f" y="%.0f" font-size="11" fill="#6b7280" text-anchor="middle">%s</text>`+"\n", x.at, head-3, sec)
	}
	for i, g := range groups {
		y := head + rowH*float64(i)
		fmt.Fprintf(w, `<text x="%.0f" y="%.1f" font-weight="600" fill="#111827">%s</text>`+"\n", left, y+16, html.EscapeString(g.Label))
		pass := 0.0
		if g.Runs > 0 {
			pass = barW * float64(g.Passed) / float64(g.Runs)
		}
		fmt.Fprintf(w, `<rect x="%.0f" y="%.1f" width="%.1f" height="14" fill="#059669"><title>%d of %d runs passed</title></rect>`, left, y+24, pass, g.Passed, g.Runs)
		fmt.Fprintf(w, `<rect x="%.1f" y="%.1f" width="%.1f" height="14" fill="#dc2626"><title>%d of %d runs failed</title></rect>`+"\n", left+pass, y+24, barW-pass, g.Runs-g.Passed, g.Runs)
		txt := fmt.Sprintf("%d of %d runs passed", g.Passed, g.Runs)
		if g.ByDesign {
			txt += " (failure expected)"
		}
		fmt.Fprintf(w, `<text x="%.0f" y="%.1f" fill="#374151">%s</text>`+"\n", left+barW+10, y+36, html.EscapeString(txt))
		for _, c := range []struct {
			at float64
			v  int64
		}{{colLedger, g.LedgerViolations}, {colDup, g.DuplicateCharges}, {colDead, g.Deadlocks}} {
			col := "#111827"
			if c.v > 0 {
				col = "#b91c1c"
			}
			fmt.Fprintf(w, `<text x="%.0f" y="%.1f" text-anchor="middle" font-size="14" font-weight="600" fill="%s">%s</text>`+"\n", c.at, y+36, col, thousands(float64(c.v)))
		}
		if g.Note != "" {
			fmt.Fprintf(w, `<text x="%.0f" y="%.1f" font-size="11" fill="#6b7280">%s</text>`+"\n", left, y+rowH-8, html.EscapeString(g.Note))
		}
		fmt.Fprintf(w, `<line x1="%.0f" x2="%.0f" y1="%.1f" y2="%.1f" stroke="#e5e7eb"/>`+"\n", left, width-20, y+rowH, y+rowH)
	}
	fmt.Fprintf(w, `<text x="%.0f" y="%.0f" font-size="11" fill="#6b7280">Counts are totals over the runs listed; they describe those runs only.</text>`+"\n", left, height-12)
	fmt.Fprintln(w, `</svg>`)
}
